/**
 * ============================================================================
 *  MOCK DATA — NOT FROM WIX.
 *  Used only when WIX_CLIENT_ID is unset, so the storefront builds, renders
 *  and can be SEO-audited without a Wix site. Shapes mirror what the Wix
 *  provider returns. Images are local SVG placeholders in /public/mock-media
 *  (generated by scripts/gen-mock-media.mjs).
 *  The UI shows a "demo data" notice and responses carry `X-Data-Source: mock`.
 * ============================================================================
 */
import type { Collection, Product } from '#/lib/types'
import type { CatalogProvider } from './provider'
import { ALL_PRODUCTS_COLLECTION_ID } from './provider'

