function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/\(.*?\)/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
}

const usd = (n: number) =>
  new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(n)

export const MOCK_PRODUCTS: Array<Product> = SEED.map(
  ([name, collectionId, price, adjective, ribbon], i) => {
    const slug = slugify(name)
    const onSale = i % 7 === 3
    const salePrice = onSale ? Math.round(price * 0.8) : undefined
    const outOfStock = i % 11 === 9
    const collectionName = COLLECTIONS.find((c) => c.id === collectionId)!.name
    const text = `Our ${adjective} ${name.toLowerCase()} is made in small batches from responsibly sourced materials. Designed to be used every day and built to last, it ships free on orders over $75 with 30-day returns.`
    return {
      id: `mock-${String(i + 1).padStart(3, '0')}`,
      slug,
      name,
      descriptionHtml: `<p>${text}</p><ul><li>Responsibly sourced materials</li><li>Small-batch production</li><li>Free returns within 30 days</li></ul>`,
      descriptionText: text,
      sku: `WSS-${String(1000 + i)}`,
      brand: 'Wix SEO Store',
      currency: 'USD',
      price,
      salePrice,
      formattedPrice: usd(price),
      formattedSalePrice: salePrice ? usd(salePrice) : undefined,
      availability: outOfStock ? 'OutOfStock' : 'InStock',
      inStock: !outOfStock,
      images: [0, 1].map((v) => ({
        src: `/mock-media/${slug}-${v + 1}.svg`,
        width: 1200,
        height: 1200,
        alt: v === 0 ? `${name} — ${collectionName}` : `${name}, alternate view`,
      })),
      collectionIds: [ALL_PRODUCTS_COLLECTION_ID, collectionId],
      updatedAt: new Date(Date.UTC(2026, 8, 1 + (i % 28), 12)).toISOString(),
      ribbon,
    }
  },
)

export const MOCK_COLLECTIONS: Array<Collection> = COLLECTIONS.map((c) => ({
  ...c,
  image: {
    src: `/mock-media/collection-${c.slug}.svg`,
    width: 1200,
    height: 1200,
    alt: `${c.name} collection`,
  },
}))

export function createMockProvider(): CatalogProvider {
  return {
    source: 'mock',
    listCollections: async () => MOCK_COLLECTIONS,
    getCollectionBySlug: async (slug) =>
      MOCK_COLLECTIONS.find((c) => c.slug === slug) ?? null,
    listProducts: async ({ collectionId, limit, offset }) => {
      const all = collectionId
        ? MOCK_PRODUCTS.filter((p) => p.collectionIds.includes(collectionId))
        : MOCK_PRODUCTS
      return { items: all.slice(offset, offset + limit), total: all.length }
    },
    getProductBySlug: async (slug) => MOCK_PRODUCTS.find((p) => p.slug === slug) ?? null,
    searchProducts: async (query, limit) => {
      const q = query.toLowerCase()
      return MOCK_PRODUCTS.filter((p) => p.name.toLowerCase().includes(q)).slice(0, limit)
    },
    listAllProductsForSitemap: async () =>
      MOCK_PRODUCTS.map((p) => ({
        slug: p.slug,
        updatedAt: p.updatedAt,
        collectionIds: p.collectionIds,
      })),
  }
}
